"var LK={acc:'orange',fav:'heart'},ACC={orange:['#ff9f43','#d35f00'],blue:['#4da3ff','#0a66d1'],green:['#3ccf7a','#1a8f4c'],purple:['#b48cff','#7a4fd6'],red:['#ff6b6b','#cc2b2b']};\n"
"try{var lk=JSON.parse(localStorage.getItem('look')||'{}');if(ACC[lk.acc])LK.acc=lk.acc;if(lk.fav==='star')LK.fav='star'}catch(e){}\n"
"function look(){var lt=matchMedia('(prefers-color-scheme: light)').matches?1:0,d=document.documentElement.style;d.setProperty('--acc',ACC[LK.acc][lt]);\n"
"d.setProperty('--fav',LK.fav==='star'?['#ffcc33','#c99700'][lt]:['#ff4d5e','#d61f3b'][lt]);try{localStorage.setItem('look',JSON.stringify(LK))}catch(e){}\n"
"[].forEach.call(document.querySelectorAll('.fa'),function(b){star(b,/9733|9829|\\u2605|\\u2665/.test(b.innerHTML)||b.innerHTML==='\\u2605'||b.innerHTML==='\\u2665')})}\n"
"var $=function(i){return document.getElementById(i)};\n"
"function fm(ms){var s=Math.floor(ms/1000);return Math.floor(s/60)+':'+('0'+s%60).slice(-2)}\n"
"function enc(o){return Object.keys(o).map(function(k){return k+'='+encodeURIComponent(o[k])}).join('&')}\n"
"var mt;function say(t,ok){var m=$('msg');m.textContent=t||'';m.className=ok?'':'err';clearTimeout(mt);if(ok)mt=setTimeout(function(){say('')},2500)}\n"
"function cmdj(c,b){return fetch('api/'+c,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b||''})\n"
".then(function(r){return r.json().then(function(j){say(j.ok?'':(j.message||'Not possible right now'));setTimeout(refresh,300);return j})})\n"
".catch(function(){say('Player not reachable');return{}})}\n"
"function cmd(c,b){return cmdj(c,b).then(function(j){return !!j.ok})}\n"
"function star(b,on){b.classList.add('fa');b.innerHTML=LK.fav==='star'?(on?'&#9733;':'&#9734;'):(on?'&#9829;':'&#9825;');b.setAttribute('aria-label',on?'Remove from favourites':'Save to favourites')}\n"
"/* edits: a bottom sheet of actions; prompt/confirm for names and deletes */\n"
"function sheet(t,acts){var s=$('sh');s.textContent='';var h=document.createElement('b');h.textContent=t;s.appendChild(h);\n"
"acts.concat([['Cancel',null]]).forEach(function(a){var b=document.createElement('button');b.textContent=a[0];b.onclick=function(){shut();if(a[1])a[1]()};s.appendChild(b)});\n"
"s.classList.remove('hide');$('shb').classList.remove('hide')}\n"
"/* After the list ends (own player): the station (a radio favourite) or a playlist, played once, again and again, or shuffled */\n"
"var PLF=['once','again and again','again and again','shuffled','shuffled'];function lesay(le){return le.mode===2?(le.station?'Station: '+le.station:'No station chosen yet'):le.mode===3?(le.pl_id?'Playlist: '+(le.playlist||'(deleted)')+', '+PLF[le.pl_flags&2?3:le.pl_flags]:'No playlist chosen yet'):''}\n"
"function lpick(m,then){fetch('api/library/'+(m==3?'playlists':'radio')+'?limit=500',{cache:'no-store'}).then(function(r){return r.json()}).then(function(j){var a=(j.items||[]).map(function(x){return[x.name,function(){\n"
"if(m==3)sheet(x.name,[['In order, once',0],['In order, again and again',1],['Shuffled',2]].map(function(f){return[f[0],function(){cmd('list_end',enc({mode:3,pl:x.id,flags:f[1]})).then(function(ok){if(ok)say('Plays '+x.name+' after the list',1);if(then)then()})}]}));\n"
"else cmd('list_end',enc({mode:2,pos:x.pos,url:x.url})).then(function(ok){if(ok)say('Plays '+x.name+' after the list',1);if(then)then()})}]});\n"
"if(!a.length){say(m==3?'No playlists yet':'No radio favourites yet - save stations in the Radio tab');return}sheet(m==3?'Playlist after the list':'Station after the list',a)}).catch(function(){say('Player not reachable')})}\n"
"/* a stream address of your own (not in the station directory): its name and URL */\n"
"function askurl(then){var u=prompt('Stream address (http:// or https://)','https://');if(!u||!/^https?:\\/\\/./i.test(u.trim())){if(u)say('That is not a stream address (http:// or https://)');return}\n"
"var n=prompt('Name of the station',u.trim().replace(/^https?:\\/\\//i,'').split(/[/?]/)[0]);if(!n||!n.trim())return;then(n.trim(),u.trim())}\n"
"function shut(){$('sh').classList.add('hide');$('shb').classList.add('hide')}\n"
"look();try{matchMedia('(prefers-color-scheme: light)').addEventListener('change',look)}catch(e){}\n"
"var V='status';\n"
"function status(){if(V!=='status'||document.hidden)return;fetch('api/status',{cache:'no-store'}).then(function(r){return r.json()}).then(function(j){if(V!=='status'||!j.ok)return;var d=$('stv');d.textContent='';\n"
"if(document.activeElement!==$('wm')&&j.work_mode>=0&&j.work_mode<6)$('wm').value=j.work_mode;var sc=j.scan&&j.scan.active,rb=document.createElement('button');rb.className='more';rb.textContent=sc?'Stop library scan':'Rescan library';\n"
"rb.onclick=function(){if(!sc&&!confirm('Rescan the library on the SD card now? Large cards take a while.'))return;cmd('rescan','action='+(sc?'stop':'start')).then(function(ok){if(ok){say(sc?'Stopping the scan':'Scanning the library',1);setTimeout(status,500)}})};d.appendChild(rb);\n"
"j.groups.forEach(function(g){if(!g.rows.length)return;var h=document.createElement('h2');h.textContent=g.name;d.appendChild(h);var c=document.createElement('div');c.id='';c.className='card';c.style.padding='0';\n"
"g.rows.forEach(function(r){var k=document.createElement('div');k.className='kv';var a=document.createElement('span'),b=document.createElement('span');a.textContent=r[0];b.textContent=r[1];k.appendChild(a);k.appendChild(b);c.appendChild(k)});d.appendChild(c)})}).catch(function(){say('Player not reachable')})}\n"
"setInterval(status,3000);\n"
"$('wm').onchange=function(){var m=$('wm').value;if(m==='3'&&!confirm('Switch to USB storage? The card goes to the computer: the library, playback and this page\\u2019s lists stop until you switch back.'))return status();\n"
"cmd('work_mode','mode='+m).then(function(ok){if(ok)say('Switching mode',1);setTimeout(status,3500)})};\n"
"$('rbt').onclick=function(){if(!confirm('Restart the Disc now? This page reconnects once it is back (about a minute).'))return;cmd('reboot','confirm=1').then(function(ok){if(ok)say('Restarting…',1)})};\n"
"/* Bluetooth: the Disc's own Bluetooth screen calls; a search takes ~15 s, connecting a few seconds */\n"
"var bton=0;function bt(){if(V!=='bt'||document.hidden)return;fetch('api/bluetooth',{cache:'no-store'}).then(function(r){return r.json()}).then(function(j){if(V!=='bt'||!j.ok)return;\n"
"var k=j.codec,e=$('btk');$('btc').classList.toggle('hide',!k||!k.settable);if(k&&k.settable&&document.activeElement!==e){if(e.options.length!==k.choices.length){e.textContent='';k.choices.forEach(function(c){var o=document.createElement('option');o.value=c.id;o.textContent=c.name;e.appendChild(o)})}\n"
"e.value=k.current;$('bth').textContent=(k.choices[k.current]||{}).hint||''}$('btn').textContent=k&&k.live?'· now '+k.live:'';\n"
"var on=j.state==='on';bton=j.state!=='off';$('bts').textContent=on?(j.busy?'Looking for devices…':'Bluetooth is on'):j.state==='off'?'Bluetooth is off':'Turning on…';\n"
"$('bto').textContent=bton?'Turn off':'Turn on';$('bto').className=bton?'':'pa';$('btf').disabled=!on||j.busy;var l=$('btl');l.textContent='';\n"
"if(on&&!j.devices.length){l.className='card';l.textContent=j.busy?'Searching…':'No audio devices found. Put your headphones in pairing mode and search.';return}l.className=j.devices.length?'card':'';l.style.padding='0';\n"
"j.devices.forEach(function(d){var w=document.createElement('div');w.className='rw';var b=document.createElement('button');b.className='r';var t=document.createElement('b'),m=document.createElement('small');\n"
"t.textContent=(d.connected?'\\u25cf ':'')+d.name;m.textContent=d.connected?'Connected'+(d.codec?' · '+d.codec:'')+(d.battery>=0?' · battery '+d.battery+' %':'')+' · tap to disconnect':(d.alias&&d.own?d.own+' · ':'')+d.mac;b.appendChild(t);b.appendChild(m);\n"
"b.onclick=function(){cmd('bt_device',enc({action:d.connected?'disconnect':'connect',mac:d.mac})).then(function(ok){if(ok){say(d.connected?'Disconnecting…':'Connecting to '+d.name+'…',1);setTimeout(bt,1500)}})};\n"
"var x=document.createElement('button');x.className='st';x.innerHTML='&#8943;';x.setAttribute('aria-label','More');x.onclick=function(){sheet(d.name,[['Rename…',function(){var n=prompt('Name on this Disc (empty: the device\\u2019s own name)',d.alias||d.name);if(n===null)return;\n"
"cmd('bt_device',enc({action:'rename',mac:d.mac,name:n.trim()})).then(function(ok){if(ok){say('Renamed',1);bt()}})}],['Forget device',function(){if(!confirm('Forget “'+d.name+'”? You will need to pair it again.'))return;\n"
"cmd('bt_device',enc({action:'forget',mac:d.mac})).then(function(ok){if(ok){say('Device forgotten',1);setTimeout(bt,1800)}})}]])};w.appendChild(b);w.appendChild(x);l.appendChild(w)})}).catch(function(){say('Player not reachable')})}\n"
"setInterval(bt,2000);$('bto').onclick=function(){cmd('bluetooth','action='+(bton?'off':'on')).then(function(ok){if(ok){say(bton?'Turning Bluetooth off':'Turning Bluetooth on - this takes up to half a minute',1);setTimeout(bt,500)}})};\n"
"$('btk').onchange=function(){cmd('bluetooth',enc({action:'codec',codec:$('btk').value})).then(function(ok){if(ok){say('Saved - applies from the next connection',1);bt()}})};\n"
"$('btf').onclick=function(){cmd('bluetooth','action=search').then(function(ok){if(ok){$('btf').disabled=true;say('Searching for about 15 seconds',1);setTimeout(bt,500)}})};\n"
"/* Screen: a picture of the Disc's screen on request (Live: again a moment after each one arrives); touches on it are sent */\n"
"var sbusy=0,sdn=null;function shot(){if(V!=='scr'||document.hidden||sbusy)return;sbusy=1;$('si').src='api/screen?t='+Date.now()}\n"
"$('si').onload=function(){sbusy=0;if($('sau').checked)setTimeout(shot,700)};$('si').onerror=function(){sbusy=0;say('The screen could not be read');if($('sau').checked)setTimeout(shot,3000)};\n"
"$('srf').onclick=shot;$('sau').onchange=shot;\n"
"function spt(e){var r=$('si').getBoundingClientRect(),f=function(v){return Math.max(0,Math.min(359,Math.round(v*360)))};return{x:f((e.clientX-r.left)/r.width),y:f((e.clientY-r.top)/r.height)}}\n"
"$('si').onpointerdown=function(e){e.preventDefault();sdn=spt(e);sdn.t=Date.now();try{$('si').setPointerCapture(e.pointerId)}catch(x){}};\n"
"$('si').onpointercancel=function(){sdn=null};$('si').ondragstart=function(){return false};\n"
"$('si').onpointerup=function(e){if(!sdn)return;var a=sdn,b=spt(e),ms=Math.min(3000,Date.now()-a.t);sdn=null;\n"
"if(Math.abs(b.x-a.x)<5&&Math.abs(b.y-a.y)<5){b=a;if(ms<350)ms=100}\n"
"cmd('touch',enc({x:a.x,y:a.y,x2:b.x,y2:b.y,ms:ms})).then(function(ok){setTimeout(shot,(ok?ms:0)+450);if(ok&&!$('sau').checked)setTimeout(shot,ms+1500)})};\n"
"/* Party: the guests' link and what guests may do (api/party); \"When the queue is empty\" is After the list ends */\n"
"function party(){if(V!=='party'||document.hidden)return;fetch('api/party',{cache:'no-store'}).then(function(r){return r.json()}).then(function(j){if(V!=='party'||!j.ok)return;var c=j.settings;\n"
"[].forEach.call(document.querySelectorAll('#ptv [data-k]'),function(e){if(document.activeElement===e)return;if(e.type==='checkbox')e.checked=!!c[e.dataset.k];else e.value=c[e.dataset.k]});$('pmvv').textContent=$('pmv').value;\n"
"if(document.activeElement!==$('pnm')&&!$('pnm').dataset.e)$('pnm').value=c.name;var u=c.name?location.origin+'/'+c.name+'/':'';$('plw').classList.toggle('hide',!u);$('pl').textContent=u+(c.on?'':' (off)');\n"
"var g=$('pg');g.textContent='';if(!j.guests.length)g.textContent='None yet';g.style.padding=j.guests.length?'0':'';j.guests.forEach(function(x){var k=document.createElement('div');k.className='kv';var a=document.createElement('span'),b=document.createElement('span');\n"
"a.textContent=x.name||'(no name)';b.textContent=x.queued+' queued · seen '+(x.seen_s<60?'just now':Math.round(x.seen_s/60)+' min ago');k.appendChild(a);k.appendChild(b);g.appendChild(k);\n"
"(x.stations||[]).forEach(function(t){var d=document.createElement('div');d.className='hint';d.style.padding='0 1em .3em';d.textContent='\\u2665 '+t.name+' \\u2014 '+t.url;g.appendChild(d)})})}).catch(function(){say('Player not reachable')});\n"
"fetch('api/state',{cache:'no-store'}).then(function(r){return r.json()}).then(function(s){var le=s.list_end;$('pe').disabled=!le;$('pen').textContent=le?'The same setting as After the list ends on the Disc and on the Remote page.':'Only with the own player (Settings > Playback).';\n"
"if(le){if(document.activeElement!==$('pe'))$('pe').value=le.mode;$('psw').classList.toggle('hide',le.mode<2);$('pes').textContent=lesay(le)}else $('psw').classList.add('hide')}).catch(function(){})}\n"
"setInterval(party,3000);\n"
"[].forEach.call(document.querySelectorAll('#ptv [data-k]'),function(e){if(e.type==='range')e.oninput=function(){$('pmvv').textContent=e.value};\n"
"e.onchange=function(){var v=e.type==='checkbox'?(e.checked?1:0):e.value;cmd('party',e.dataset.k+'='+encodeURIComponent(v)).then(function(ok){if(ok)say('Saved',1);party()})}});\n"
"$('pnm').oninput=function(){$('pnm').dataset.e=1};$('pns').onclick=function(){var n=$('pnm').value.trim();cmd('party',enc({name:n})).then(function(ok){if(ok){$('pnm').dataset.e='';say('Saved',1)}party()})};\n"
"$('plc').onclick=function(){var t=$('pl').textContent.split(' ')[0];try{navigator.clipboard.writeText(t).then(function(){say('Link copied',1)},function(){prompt('The guests\\u2019 link',t)})}catch(e){prompt('The guests\\u2019 link',t)}};\n"
"$('pe').onchange=function(){var m=$('pe').value;cmd('list_end','mode='+m).then(function(ok){if(!ok&&m>1)lpick(m,party);party()});$('pe').blur()};$('psc').onclick=function(){lpick($('pe').value,party)};\n"
"function refresh(){status();bt();party()}\n"
"function tab(v){if(!$(v+'t'))v='status';V=v;[].forEach.call($('tabs').children,function(b){b.classList.toggle('on',b.dataset.v===v)});try{history.replaceState(null,'','#'+v)}catch(e){}\n"
"$('scv').classList.toggle('hide',v!=='scr');$('stv').classList.toggle('hide',v!=='status');$('sys').classList.toggle('hide',v!=='status');$('btv').classList.toggle('hide',v!=='bt');$('ptv').classList.toggle('hide',v!=='party');say('');\n"
"if(v==='scr'){shot();return}if(v==='party'){party();return}if(v==='status'){$('stv').textContent='Loading…';status();return}$('btl').textContent='Loading…';bt()}\n"
"[].forEach.call($('tabs').children,function(b){b.onclick=function(){tab(b.dataset.v)}});\n"
"$('lka').value=LK.acc;$('lkf').value=LK.fav;$('lka').onchange=function(){LK.acc=$('lka').value;look()};$('lkf').onchange=function(){LK.fav=$('lkf').value;look()};\n"
"document.addEventListener('visibilitychange',function(){refresh();shot()});tab(location.hash.slice(1));\n"
"</script></html>\n";

